<?php
 namespace Pterodactyl\Services\Dezerx\ServerCreate; use Pterodactyl\Models\Egg; use Pterodactyl\Models\User; use Pterodactyl\Models\Server; use Pterodactyl\Models\Location; use Pterodactyl\Models\EggVariable; use Pterodactyl\Models\Dezerx\FreeServer; class ServerCreatePresenter { public function __construct(private NodeCapacity $capacity) { } private function discord(User $user): array { $link = Discord::required() ? Discord::linkFor($user) : null; return [ 'required' => Discord::required(), 'joinsGuild' => Discord::required() && Discord::joins(), 'linked' => $link !== null, 'username' => $link?->username, 'avatar' => $link?->avatarUrl(), 'canUnlink' => $link !== null && !$user->demo && ServerCreate::held($user) === 0, ]; } public function page(User $user): array { $refusal = ServerCreate::refusal($user); $room = $this->capacity->byLocation((array) ServerCreate::setting('locations')); return [ 'enabled' => ServerCreate::usable(), 'available' => $refusal === null, 'refusal' => $refusal, 'remaining' => ServerCreate::remaining($user), 'held' => ServerCreate::held($user), 'perUser' => ServerCreate::allowedServers($user), 'namePrefix' => (string) ServerCreate::setting('name_prefix'), 'requireTotp' => ServerCreate::flag('require_totp'), 'discord' => $this->discord($user), 'minAccountAgeHours' => ServerCreate::number('min_account_age_hours'), 'resources' => ServerCreate::resources(), 'custom' => ServerCreate::custom(), 'units' => ServerCreate::units(), 'demoServer' => $this->demoServer($user), 'limits' => $this->limits($user), 'startsOnCreation' => ServerCreate::flag('start_on_completion'), 'locations' => ServerCreate::locations() ->map(function (Location $location) use ($room) { $stats = $room[(int) $location->id] ?? ['room' => false, 'slots' => 0, 'total' => 0, 'servers' => 0, 'node' => '']; $note = ServerCreate::locationNote((int) $location->id); return [ 'id' => (int) $location->id, 'name' => $location->short, 'description' => $note !== '' ? $note : (string) $location