 => [ 'cpu' => (int) $server->cpu, 'memory' => (int) $server->memory, 'disk' => (int) $server->disk, 'databases' => (int) $server->database_limit, 'allocations' => (int) $server->allocation_limit, 'backups' => (int) $server->backup_limit, ], 'limits' => $limits, ]; } public function entry(FreeServer $entry): array { $server = $entry->server; return [ 'uuid' => (string) $server?->uuid, 'identifier' => (string) $server?->uuidShort, 'name' => (string) $server?->name, 'renewAt' => $entry->renew_at?->toIso8601String(), 'lastRenewedAt' => $entry->last_renewed_at?->toIso8601String(), 'renewals' => $entry->renewals, 'renewable' => ServerCreate::renewals() && ServerCreate::withinWindow($entry->renew_at), 'overdue' => ServerCreate::renewals() && $entry->isOverdue(), 'suspended' => $entry->wasSuspendedForNonRenewal(), ]; } public function renewals(): array { return [ 'enabled' => ServerCreate::renewals(), 'every' => ServerCreate::number('renew_every'), 'unit' => (string) ServerCreate::setting('renew_unit'), 'period' => ServerCreate::period(), 'windowHours' => ServerCreate::number('renew_window_hours'), 'graceHours' => ServerCreate::number('grace_hours'), 'action' => (string) ServerCreate::setting('expire_action'), 'purgeDays' => ServerCreate::number('purge_days'), ]; } private function egg(Egg $egg): array { $images = array_values((array) $egg->docker_images); return [ 'uuid' => $egg->uuid, 'name' => $egg->name, 'description' => (string) $egg->description, 'nest' => (string) ($egg->nest?->name ?? ''), 'image' => $images[0] ?? '', 'variables' => ServerCreate::flag('variables') ? $this->variables($egg) : [], ]; } private function variables(Egg $egg): array { return $egg->variables() ->where('user_viewable', true) ->where('user_editable', true) ->orderBy('id') ->get() ->map(fn (EggVariable $variable) => [ 'name' => $variable->name, 'description' => (string) $variable->description, 'env' => $variable->env_variable, 'default' => (string) $variable->default_value, 'required' => str_